window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-96394308059a0a6a"]={"versions": [{"id": "FIG-96394308059a0a6a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P04mCheck()</code> in der Client-Überladung (<code>client overload</code>) gemäß AUTOSAR End-to-End-Protokoll (Profil 4m). Das Diagramm modelliert die Validierung, Deserialisierung und Prüfung empfangener Nachrichten auf Client-Seite innerhalb des AUTOSAR E2E-Frameworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsschnittstelle / Aufruf:</strong> <code>E2E_P04mCheck(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code> (im Diagrammkopf abgeschnitten dargestellt als <code>Data,</code>).</li>\n<li><strong>Verzweigungselemente (Decisions):</strong></li>\n<li>Verzweigung nach <code>Verify inputs of the check function</code>: Guards <code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code>.</li>\n<li>Verzweigung nach Datenverfügbarkeit: Bedingung <code>NewDataAvailable == TRUE</code> mit Guards <code>[TRUE]</code> und <code>[FALSE]</code>.</li>\n<li><strong>Aktionen (Sub-Aktivitäten mit Refinement-Symbol):</strong></li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Ablaufelemente:</strong></li>\n<li>Startknoten (Initial Node)</li>\n<li>Drei Aktivitätsendknoten (Activity Final Nodes) mit Rückkehr (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten und führt direkt zur Aktion <code>Verify inputs of the check function</code>.</li>\n<li>Ergibt die Eingangsprüfung einen Null-Zeiger (<code>[null input]</code>), verzweigt der Pfad unmittelbar auf einen linken Aktivitätsendknoten (<code>return</code>, korrespondierend zu <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Bei fehlerhaften Eingabeparametern (<code>[wrong input]</code>) zweigt der Pfad auf den rechten Aktivitätsendknoten ab (<code>return</code>, korrespondierend zu <code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Bei gültigen Eingaben (<code>[input ok]</code>) folgt die Verzweigung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[FALSE]</code>: Umgeht die Deserialisierung und CRC-Berechnung und führt direkt zur Aktion <code>Do checks</code>.</li>\n<li>Zweig <code>[TRUE]</code>: Durchläuft sequenziell die Aktionen:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n</ul>\n<p class=\"fig-p\">und mündet anschließend ebenfalls in <code>Do checks</code>.</p>\n<ol class=\"fig-list\">\n<li>Nach Ausführung von <code>Do checks</code> endet der Hauptpfad am mittleren Aktivitätsendknoten (<code>return</code>, korrespondierend zu <code>E2E_E_OK</code> bzw. dem ermittelten Zustand).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativer Bestandteil der Anforderung <code>[PRS_E2E_00772]</code> zur Festlegung des Gesamtverhaltens von <code>E2E_P04mCheck()</code> für Clients. Die einzelnen Aktionen mit Refinement-Symbol (<code>Compute offset</code>, <code>Read ...</code>, <code>Compute CRC</code>, <code>Do checks</code>, <code>Verify inputs...</code>) verweisen auf detaillierte Unternormen (z. B. <code>[PRS_E2E_00773]</code>). Implementierungen müssen zwingend die exakte Auswertungsreihenfolge der Header-Felder, die Umgehung bei ausbleibenden Neudaten (<code>NewDataAvailable == FALSE</code>) sowie die getrennte Fehlerbehandlung für Null- und Falscheingaben einhalten.</p>"}, {"id": "FIG-cecfa806875a3207", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Funktion <code>E2E_P04mCheck()</code> in der Client-Überladung (<code>client overload</code>) gemäß AUTOSAR End-to-End-Protokoll (Profil 4m). Das Diagramm modelliert die Validierung, Deserialisierung und Prüfung empfangener Nachrichten auf Client-Seite innerhalb des AUTOSAR E2E-Frameworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsschnittstelle / Aufruf:</strong> <code>E2E_P04mCheck(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code> (im Diagrammkopf abgeschnitten dargestellt als <code>Data,</code>).</li>\n<li><strong>Verzweigungselemente (Decisions):</strong></li>\n<li>Verzweigung nach <code>Verify inputs of the check function</code>: Guards <code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code>.</li>\n<li>Verzweigung nach Datenverfügbarkeit: Bedingung <code>NewDataAvailable == TRUE</code> mit Guards <code>[TRUE]</code> und <code>[FALSE]</code>.</li>\n<li><strong>Aktionen (Sub-Aktivitäten mit Refinement-Symbol):</strong></li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Ablaufelemente:</strong></li>\n<li>Startknoten (Initial Node)</li>\n<li>Drei Aktivitätsendknoten (Activity Final Nodes) mit Rückkehr (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss beginnt am Startknoten und führt direkt zur Aktion <code>Verify inputs of the check function</code>.</li>\n<li>Ergibt die Eingangsprüfung einen Null-Zeiger (<code>[null input]</code>), verzweigt der Pfad unmittelbar auf einen linken Aktivitätsendknoten (<code>return</code>, korrespondierend zu <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Bei fehlerhaften Eingabeparametern (<code>[wrong input]</code>) zweigt der Pfad auf den rechten Aktivitätsendknoten ab (<code>return</code>, korrespondierend zu <code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Bei gültigen Eingaben (<code>[input ok]</code>) folgt die Verzweigung <code>NewDataAvailable == TRUE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zweig <code>[FALSE]</code>: Umgeht die Deserialisierung und CRC-Berechnung und führt direkt zur Aktion <code>Do checks</code>.</li>\n<li>Zweig <code>[TRUE]</code>: Durchläuft sequenziell die Aktionen:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read SourceID</code></li>\n<li><code>Read Message Type</code></li>\n<li><code>Read Message Result</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n</ul>\n<p class=\"fig-p\">und mündet anschließend ebenfalls in <code>Do checks</code>.</p>\n<ol class=\"fig-list\">\n<li>Nach Ausführung von <code>Do checks</code> endet der Hauptpfad am mittleren Aktivitätsendknoten (<code>return</code>, korrespondierend zu <code>E2E_E_OK</code> bzw. dem ermittelten Zustand).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativer Bestandteil der Anforderung <code>[PRS_E2E_00772]</code> zur Festlegung des Gesamtverhaltens von <code>E2E_P04mCheck()</code> für Clients. Die einzelnen Aktionen mit Refinement-Symbol (<code>Compute offset</code>, <code>Read ...</code>, <code>Compute CRC</code>, <code>Do checks</code>, <code>Verify inputs...</code>) verweisen auf detaillierte Unternormen (z. B. <code>[PRS_E2E_00773]</code>). Implementierungen müssen zwingend die exakte Auswertungsreihenfolge der Header-Felder, die Umgehung bei ausbleibenden Neudaten (<code>NewDataAvailable == FALSE</code>) sowie die getrennte Fehlerbehandlung für Null- und Falscheingaben einhalten.</p>"}], "trans": [{"from": "FIG-96394308059a0a6a", "to": "FIG-cecfa806875a3207", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
